caddy:
https://shop.example.com {
    bind 0.0.0.0
    tls /etc/caddy/orbit-certificates/app-instance-1/current/cert.pem /etc/caddy/orbit-certificates/app-instance-1/current/key.pem
    root * /home/orbit-shop/current/public
encode zstd gzip
php_fastcgi unix//run/php/orbit-shop.sock {
    resolve_root_symlink
}
file_server
}

https://site.example.com {
    bind 0.0.0.0
    tls /etc/caddy/orbit-certificates/app-instance-2/current/cert.pem /etc/caddy/orbit-certificates/app-instance-2/current/key.pem
    root * /home/orbit-site/current/apps/site/public
encode zstd gzip
php_fastcgi unix//run/php/orbit-site.sock {
    resolve_root_symlink
}
file_server
}
